_elementor_page_settings.custom_css:
/* Native layout; only intrinsic media, WordPress content and focus need scoped rules. */
.elementor-15714 .cm-case-cover img{display:block;width:100%!important;height:auto!important;aspect-ratio:16/9;object-fit:cover;object-position:center center;max-width:100%;max-height:none;margin-inline:auto}
.elementor-15714 .cm-case-main h2{font-family:Kanit,sans-serif;font-size:clamp(20px,1.8vw,26px);font-weight:400;line-height:1.2;letter-spacing:.025em;text-transform:uppercase;margin:32px 0 16px}
.elementor-15714 .cm-case-main h2:first-child{margin-top:0}
.elementor-15714 .cm-case-main .gallery img{border:0!important;width:100%;height:auto}
.elementor-15714 .cm-case-main iframe{width:100%;height:auto;aspect-ratio:16/9;border:0}
.elementor-15714 .elementor-icon-list-item:not(:has(.elementor-post-info__terms-list-item)){display:none}
.elementor-15714 .btn .elementor-button:focus-visible{outline:2px solid var(--e-global-color-accent);outline-offset:4px}

.elementor-15714 .cm-case-breadcrumb{margin:0 0 20px;font-size:14px}
.elementor-15714 .cm-case-breadcrumb a{color:inherit;text-decoration:underline}
.elementor-15714 .cm-case-related .elementor-loop-container{align-items:stretch}
.elementor-15714 .cm-case-final{border-top:1px solid #e1e6dc;margin-top:48px}
.elementor-15714 .cm-case-final .elementor-widget-text-editor{max-width:65ch}
.elementor-15714 .cm-case-breadcrumb a:focus-visible{outline:2px solid var(--e-global-color-accent);outline-offset:4px}

/* Project facts: native CSS sticky is bounded by the existing content section. */
@media (min-width:1025px){
.elementor-15714 .cm-case-facts-column{position:sticky;top:88px;align-self:flex-start}
body.admin-bar .elementor-15714 .cm-case-facts-column{top:120px}
}
@media (max-width:1024px){.elementor-15714 .cm-case-facts-column{position:static;top:auto}}

/* Natural-ratio, arbitrary-length WordPress galleries; Elementor owns the lightbox. */
.elementor-15714 .cm-case-main .gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:0}
.elementor-15714 .cm-case-main .gallery .gallery-item{width:100%;max-width:none;float:none;margin:0}
.elementor-15714 .cm-case-main .gallery br{display:none}
.elementor-15714 .cm-case-main .gallery a{display:block}
.elementor-15714 .cm-case-main .gallery img{display:block;border-radius:8px}
@media(max-width:767px){.elementor-15714 .cm-case-main .gallery{grid-template-columns:minmax(0,1fr);gap:16px}}
